function onceBridgeSignal(ms) {
  return new Promise(resolve => {
    const timer = setTimeout(done, ms);
    function done() {
      clearTimeout(timer);
      window.removeEventListener("awtsmoos-server-ready", done);
      window.removeEventListener("message", onMessage);
